#include <string>
using namespace std;

class Solution {
public:
    int countSubstrings(string s, string t) {
        int ans = 0;
        int m = s.size(), n = t.size();
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                int diff = 0;
                for (int k = 0; i + k < m && j + k < n; ++k) {
                    if (s[i + k] != t[j + k]) diff++;
                    if (diff > 1) break;
                    if (diff == 1) ans++;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int countSubstrings(String s, String t) {
        int ans = 0;
        int m = s.length(), n = t.length();
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                int diff = 0;
                for (int k = 0; i + k < m && j + k < n; ++k) {
                    if (s.charAt(i + k) != t.charAt(j + k)) diff++;
                    if (diff > 1) break;
                    if (diff == 1) ans++;
                }
            }
        }
        return ans;
    }
}

